{
  "type": "custom.cart_drawer",
  "name": "t:cart_drawer",
  "sections": {
    "cart-drawer": {
      "type": "cart-drawer",
      "blocks": {
        "cart_header_blocks": {
          "type": "_cart-header-blocks",
          "static": true,
          "settings": {
            "wrap_in_card": false,
            "color_scheme": "",
            "margin_top": 0,
            "margin_bottom": 0
          },
          "blocks": {
            "nm_banner_livraison": {
              "type": "custom-code",
              "settings": {
                "show_on_display": "desktop_and_mobile",
                "custom_liquid": "<div class=\"nm-cart-banner\">\n  <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">\n    <path d=\"M1 3h15v13H1z\"/>\n    <path d=\"M16 8h4l3 3v5h-7z\"/>\n    <circle cx=\"5.5\" cy=\"18.5\" r=\"1.6\"/>\n    <circle cx=\"18.5\" cy=\"18.5\" r=\"1.6\"/>\n  </svg>\n  <span>Livraison offerte et suivie en France</span>\n</div>\n<style>\n  .nm-cart-banner{display:flex;align-items:center;justify-content:center;gap:.5rem;margin:0 var(--cart-drawer-padding,0px) var(--gap-md,.75rem);padding:.6rem 1rem;border-radius:12px;background:#0B0B0C;color:#FAFAF7;font-size:.85rem;font-weight:500}\n  .nm-cart-banner svg{width:20px;height:20px;flex-shrink:0}\n</style>",
                "margin_top": 0,
                "margin_bottom": 0,
                "additional_class": ""
              },
              "blocks": {},
              "name": "Bannière livraison offerte"
            }
          },
          "block_order": [
            "nm_banner_livraison"
          ]
        },
        "cart_footer_resume_blocks": {
          "type": "_cart-footer-resume-blocks",
          "static": true,
          "settings": {
            "wrap_in_card": false,
            "color_scheme": "",
            "margin_top": 0,
            "margin_bottom": 0
          },
          "blocks": {
            "nm_upsell": {
              "type": "custom-code",
              "settings": {
                "show_on_display": "desktop_and_mobile",
                "custom_liquid": "{%- liquid\n  assign nm_upsell = 'loupe-de-date-saphir,bracelet-fkm-tropical,rouleau-de-voyage-cuir,remontoir-solo' | split: ','\n  assign nm_count = 0\n-%}\n{%- capture nm_upsell_items -%}\n  {%- for h in nm_upsell -%}\n    {%- if nm_count >= 2 -%}{%- break -%}{%- endif -%}\n    {%- assign p = all_products[h] -%}\n    {%- if p != empty and p.available -%}\n      {%- assign in_cart = false -%}\n      {%- for item in cart.items -%}\n        {%- if item.product.handle == h -%}{%- assign in_cart = true -%}{%- endif -%}\n      {%- endfor -%}\n      {%- unless in_cart -%}\n        {%- assign v = p.selected_or_first_available_variant -%}\n        <div class=\"nm-cart-upsell__item\">\n          <a href=\"{{ p.url }}\" class=\"nm-cart-upsell__media\"><img src=\"{{ p.featured_image | image_url: width: 160 }}\" alt=\"{{ p.title | escape }}\" width=\"56\" height=\"56\" loading=\"lazy\"></a>\n          <div class=\"nm-cart-upsell__info\">\n            <a href=\"{{ p.url }}\" class=\"nm-cart-upsell__name\">{{ p.title }}</a>\n            <div class=\"nm-cart-upsell__row\">\n              <span class=\"nm-cart-upsell__price\">{{ v.price | money }}</span>\n              <form method=\"post\" action=\"{{ routes.cart_add_url }}\" class=\"nm-upsell-form\" data-nm-upsell>\n                <input type=\"hidden\" name=\"id\" value=\"{{ v.id }}\">\n                <input type=\"hidden\" name=\"quantity\" value=\"1\">\n                <button type=\"submit\" class=\"nm-upsell-add\">Ajouter</button>\n              </form>\n            </div>\n          </div>\n        </div>\n        {%- assign nm_count = nm_count | plus: 1 -%}\n      {%- endunless -%}\n    {%- endif -%}\n  {%- endfor -%}\n{%- endcapture -%}\n{%- assign nm_trim = nm_upsell_items | strip -%}\n{%- if nm_trim != '' -%}\n<div class=\"nm-cart-upsell\">\n  <p class=\"nm-cart-upsell__title\">Complétez votre collection</p>\n  <div class=\"nm-cart-upsell__list\">{{ nm_upsell_items }}</div>\n</div>\n{%- endif -%}\n<style>\n  .nm-cart-upsell{padding-block:var(--gap-md,.75rem);border-top:1px solid rgb(11 11 12 / .08);margin-block-start:var(--gap-sm,.5rem)}\n  .nm-cart-upsell__title{font-family:var(--font-heading--family,inherit);color:#0B0B0C;font-size:1.02rem;margin:0 0 .8rem}\n  .nm-cart-upsell__list{display:flex;flex-direction:column;gap:.9rem}\n  .nm-cart-upsell__item{display:grid;grid-template-columns:56px 1fr;align-items:center;gap:.75rem}\n  .nm-cart-upsell__media{display:block}\n  .nm-cart-upsell__item img{width:56px;height:56px;object-fit:cover;border-radius:10px;background:#E7E4DE;display:block}\n  .nm-cart-upsell__info{display:flex;flex-direction:column;gap:.35rem;min-width:0}\n  .nm-cart-upsell__name{font-size:.85rem;line-height:1.25;color:#0B0B0C;text-decoration:none}\n  .nm-cart-upsell__name:hover{text-decoration:underline}\n  .nm-cart-upsell__row{display:flex;align-items:center;justify-content:space-between;gap:.5rem}\n  .nm-cart-upsell__price{font-size:.9rem;font-weight:600;color:#0B0B0C;white-space:nowrap}\n  .nm-upsell-form{margin:0}\n  .nm-upsell-add{border:0;cursor:pointer;background:#0B0B0C;color:#FAFAF7;font-size:.78rem;font-weight:600;padding:.4rem .85rem;border-radius:999px;white-space:nowrap;transition:background .15s ease}\n  .nm-upsell-add:hover{opacity:.88}\n</style>\n<script>\n  (function () {\n    if (window.__nmUpsellBound) return;\n    window.__nmUpsellBound = true;\n    document.addEventListener('submit', function (e) {\n      var f = e.target && e.target.closest ? e.target.closest('[data-nm-upsell]') : null;\n      if (!f) return;\n      e.preventDefault();\n      var btn = f.querySelector('.nm-upsell-add');\n      if (btn) { btn.disabled = true; btn.textContent = '\\u2026'; }\n      fetch('/cart/add.js', {\n        method: 'POST',\n        headers: { 'Content-Type': 'application/json' },\n        body: JSON.stringify({ id: Number(f.querySelector('[name=id]').value), quantity: 1 })\n      }).then(function (r) {\n        if (!r.ok) throw new Error('add failed');\n        window.location.reload();\n      }).catch(function () {\n        if (btn) { btn.disabled = false; btn.textContent = 'Ajouter'; }\n        f.removeAttribute('data-nm-upsell');\n        f.submit();\n      });\n    }, true);\n  })();\n</script>",
                "margin_top": 0,
                "margin_bottom": 0,
                "additional_class": ""
              },
              "blocks": {},
              "name": "Upsell accessoires"
            },
            "discount_code_GBacFY": {
