                "show_on_display": "desktop_only",
                "alignment_desktop": "center",
                "alignment_mobile": "center",
                "icon_size": 35,
                "margin_top": 5,
                "margin_bottom": 5,
                "additional_class": ""
              },
              "blocks": {}
            }
          },
          "block_order": [
            "payment_methods_WRBbVe"
          ]
        },
        "cart_drawer_empty_blocks": {
          "type": "_cart-drawer-empty-blocks",
          "static": true,
          "settings": {
            "show_continue_shopping_button": true,
            "wrap_in_card": false,
            "color_scheme": "",
            "margin_top": 0,
            "margin_bottom": 0
          },
          "blocks": {}
        }
      },
      "settings": {
        "cart_style": "defaut",
        "cart_drawer_width_on_desktop": "440",
        "full_width_on_mobile": false,
        "show_variant_options_labels": false,
        "show_remove_button": true,
        "show_cart_count": true,
        "color_scheme_header": "",
        "color_scheme_body": "",
        "color_scheme_elements": "scheme-1",
        "color_scheme_footer": "scheme-1"
      }
    }
  },
  "order": [
    "cart-drawer"
  ]
}

